package com.zoro.zoromart.util;
import com.google.gson.Gson;import com.google.gson.GsonBuilder;import javax.servlet.http.HttpServletResponse;import java.io.IOException;import java.util.LinkedHashMap;import java.util.Map;
/** Shared JSON response and serialization helpers. */
public final class JsonUtil {private static final Gson GSON=new GsonBuilder().serializeNulls().create();private JsonUtil(){} public static Gson gson(){return GSON;} public static void write(HttpServletResponse r,int status,Object body)throws IOException{r.setStatus(status);r.setContentType("application/json;charset=UTF-8");r.getWriter().write(GSON.toJson(body));}public static Map<String,Object> ok(Object data){Map<String,Object> m=new LinkedHashMap<>();m.put("success",true);m.put("data",data);m.put("error",null);return m;}public static Map<String,Object> error(String code,String message){Map<String,Object> e=new LinkedHashMap<>();e.put("code",code);e.put("message",message);Map<String,Object> m=new LinkedHashMap<>();m.put("success",false);m.put("data",null);m.put("error",e);return m;}}
